TLM.f("Sancti/09-20",{"officium":"S. Eustachii et Sociorum Martyrum","rule":["Gloria"],"fallback":"Commune/C3a","from":{"Introitus":"Commune/C3a","Lectio":"Commune/C3a","Graduale":"Commune/C3a","Tractus":"Commune/C3a","Evangelium":"Commune/C3a","Offertorium":"Commune/C3a","Secreta":"Commune/C3a","Communio":"Commune/C3a"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 44:15; 44:14"},{"k":"text","la":"Sapiéntiam Sanctórum narrent populi, et laudes eórum núntiet ecclésia: nómina autem eórum vivent in sǽculum sǽculi."},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sapiéntiam Sanctórum narrent populi, et laudes eórum núntiet ecclésia: nómina autem eórum vivent in sǽculum sǽculi."}],"Oratio":[{"k":"text","la":"Deus, qui nos concédis sanctórum Mártyrum tuórum Eustáchii et Sociórum ejus natalítia cólere: da nobis in ætérna beatitúdine de eórum societáte gaudére."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Lectio libri Sapientiæ"},{"k":"ref","la":"Sap 5:16-20"},{"k":"text","la":"Justi autem in perpétuum vivent, et apud Dóminum est merces eórum, et cogitátio illórum apud Altíssimum. Ideo accípient regnum decóris, et diadéma speciéi de manu Dómini: quóniam déxtera sua teget eos, et bráchio sancto suo deféndet illos. Accípiet armatúram zelus illíus, et armábit creatúram ad ultiónem inimicórum. Induet pro thoráce justítiam, et accípiet pro gálea judícium certum. Sumet scutum inexpugnábile æquitátem."}],"Graduale":[{"k":"ref","la":"Ps 123:7-8"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium."},{"k":"text","la":"Láqueus contrítus est, et nos liberáti sumus: adjutórium nostrum in nómine Dómini, qui fecit cœlum et terram. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 67:4"},{"k":"text","la":"Justi epuléntur, et exsúltent in conspéctu Dei: et delecténtur in lætítia. Alleluja."}],"Tractus":[{"k":"ref","la":"Ps 123:7-8"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium."},{"k":"text","la":"Láqueus contrítus est, et nos liberáti sumus: adjutórium nostrum in nómine Dómini, qui fecit cœlum et terram.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flebant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 6:17-23"},{"k":"text","la":"In illo témpore: Descéndens Jesus de monte, stetit in loco campéstri, et turba discipulórum ejus, et multitúdo copiósa plebis ab omni Judǽa, et Jerúsalem, et marítima, et Tyri, et Sidónis, qui venérant, ut audírent eum et sanaréntur a languóribus suis. Et, qui vexabántur a spirítibus immúndis, curabántur. Et omnis turba quærébat eum tángere: quia virtus de illo exíbat, et sanábat omnes. Et ipse, elevátis oculis in discípulos suos, dicébat: Beáti, páuperes: quia vestrum est regnum Dei. Beáti, qui nunc esurítis: quia saturabímini. Beáti, qui nunc fletis: quia ridébitis. Beáti éritis, cum vos óderint hómines, et cum separáverint vos et exprobréverint, et ejécerint nomen vestrum tamquam malum, propter Fílium hóminis. Gaudéte in illa die et exsultáte: ecce enim, merces vestra multa est in cœlo."}],"Offertorium":[{"k":"ref","la":"Ps 149:5-6"},{"k":"text","la":"Exsultábunt Sancti in glória, lætabúntur in cubílibus suis: exaltatiónes Dei in fáucibus eórum, allelúja."}],"Secreta":[{"k":"text","la":"Múnera tibi, Dómine, nostra devotiónis offérimus: quæ et pro tuórum tibi grata sint honóre Justórum, et nobis salutária, te miseránte, reddántur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:4"},{"k":"text","la":"Dico autem vobis amícis meis: Ne terreámini ab his, qui vos persequúntur."}],"Postcommunio":[{"k":"text","la":"Præsta nobis, quǽsumus, Dómine: intercedéntibus sanctis Martýribus tuis Eustáchio et Sóciis ejus; ut, quod ore contíngimus, pura mente capiámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"7e9fb54ad1b17c9a":{"t":"<i>Pomolimo se</i>.\nBože koji dopuštaš da slavimo rođendan tvojih svetih mučenika Eustahija i njegovih drugova, daj nam da se njihovu društvu radujemo u vječnom blaženstvu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji dopuštaš, da svetkujemo rođeni dan Tvojih svetih mučenika Simforose i njezinih sinova, daj nam, da se radujemo u njihovu društvu u vječnom blaženstvu, po G. n.","knRef":"Kniewald 1942, str. 640–641 (snimka 321) (OCR)"},"0b5f9e55c57d534d":{"t":"Prikazujemo ti, Gospodine, darove svoje odanosti, da ti budu mili zbog časti tvojih pravednika, a nama postanu spasonosni po tvom milosrđu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prikazujemo Ti, Gospodine, darove naše poboznosti moleći Te, da. Tebi budu dragi poradi časti Tvojih pravednika, a nama da po Tvome milosrđu budu spasonasniji, (po G. n.","knRef":"Kniewald 1942, str. 488–489 (snimka 245) (OCR)"},"39b2a2d3a960c2a0":{"t":"<i>Pomolimo se</i>.\nDaj nam, molimo, Gospodine, po zagovoru svojih svetih mučenika Eustahija i njegovih drugova da čistom dušom prihvatimo što smo ustima primili.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj nam, molimo, Gospodine, da zagovorom Tvojih svetih mučenika I. i I., čistom dušom prihvatimo, što ustima primamo, po G. n.","knRef":"Kniewald 1942, str. 806–807 (snimka 404) (OCR)"}}});
